import { sql } from "kysely";
import { Capacitor } from "@capacitor/core";
import { Geolocation } from "@capacitor/geolocation";
import { rdb } from "@/shared/database";
import { useReactiveQuery } from "@/shared/composables/useReactiveQuery";
import { useAuthStore } from "@/shared/stores/auth.store";
import {
  classifyTask,
  composeAddress,
  formatDistance,
  formatDzd,
  greetingFor,
  haversineMeters,
  partnerImageSrc,
} from "../home.format";
import type { HomeNextStop, HomePendingTask, HomeRouteStop, HomeStat } from "../home.types";

interface StopRow {
  ruid: string;
  sequence: number | null;
  validationState: string | null;
  name: string;
  street: string | null;
  street2: string | null;
  zip: string | null;
  lat: number | null;
  lng: number | null;
  image: string | null;
}

interface OrderRow {
  state: string;
  orderLine: string | null;
}

interface TaskRow {
  ruid: string;
  name: string;
  description: string | null;
  partnerName: string | null;
}

interface DerivedStop extends StopRow {
  status: "upcoming" | "completed";
}

const VISIT_TYPE = "Delivery";
const TASK_LIMIT = 6;

async function getOpenPlanningRuid(): Promise<string | null> {
  const planning = await rdb
    .selectFrom("planning_planning")
    .select("_ruid")
    .where("_delete_date", "is", null)
    .orderBy(sql`case when state = 'open' then 0 else 1 end`)
    .orderBy("date_start", "desc")
    .limit(1)
    .executeTakeFirst();
  return planning?._ruid ?? null;
}

function deriveStatus(row: StopRow): DerivedStop["status"] | null {
  if (row.validationState === "cancel") return null;
  if (row.validationState === "validated") return "completed";
  return "upcoming";
}

function sumOrderLineTotal(orderLine: string | null): number {
  if (!orderLine) return 0;
  try {
    const lines = JSON.parse(orderLine) as Array<{ price_total?: number }>;
    if (!Array.isArray(lines)) return 0;
    return lines.reduce((acc, line) => acc + Number(line?.price_total ?? 0), 0);
  } catch {
    return 0;
  }
}

export function useHomeDashboard() {
  const authStore = useAuthStore();
  const now = new Date();
  const greeting = greetingFor(now);
  const salespersonName = computed(() => authStore.user?.name?.trim() || "Welcome");

  const coords = ref<{ lat: number; lng: number } | null>(null);

  onMounted(async () => {
    try {
      if (Capacitor.isNativePlatform()) {
        const status = await Geolocation.checkPermissions();
        if (status.location !== "granted" && status.coarseLocation !== "granted") {
          await Geolocation.requestPermissions();
        }
      }
      const position = await Geolocation.getCurrentPosition({
        enableHighAccuracy: false,
        timeout: 8000,
      });
      coords.value = {
        lat: position.coords.latitude,
        lng: position.coords.longitude,
      };
    } catch {
      coords.value = null;
    }
  });

  const { data: stopsData } = useReactiveQuery<DerivedStop[]>(
    async () => {
      const planningRuid = await getOpenPlanningRuid();
      if (!planningRuid) return [];
      const rows = await rdb
        .selectFrom("calendar_event as e")
        .innerJoin("res_partner as p", "p._ruid", "e.partner_customer_id")
        .select([
          "e._ruid as ruid",
          "e.sequence as sequence",
          "e.validation_state as validationState",
          "p.name as name",
          "p.street as street",
          "p.street2 as street2",
          "p.zip as zip",
          "p.partner_latitude as lat",
          "p.partner_longitude as lng",
          "p.image_1920 as image",
        ])
        .where("e.planning_id", "=", planningRuid)
        .where("e._delete_date", "is", null)
        .where("p._delete_date", "is", null)
        .orderBy("e.sequence")
        .$castTo<StopRow>()
        .execute();

      const derived: DerivedStop[] = [];
      for (const row of rows) {
        const status = deriveStatus(row);
        if (!status) continue;
        derived.push({ ...row, status });
      }
      return derived;
    },
    {
      tables: ["planning_planning", "calendar_event", "res_partner"],
      queryKey: "home:stops",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 120,
    },
  );

  const { data: orderRows } = useReactiveQuery<OrderRow[]>(
    async () => {
      const planningRuid = await getOpenPlanningRuid();
      if (!planningRuid) return [];
      return (await rdb
        .selectFrom("sale_order")
        .select(["state", "order_line as orderLine"])
        .where("planning_id", "=", planningRuid)
        .where("_delete_date", "is", null)
        .where("state", "not in", ["cancel", "no_sale"])
        .execute()) as OrderRow[];
    },
    {
      tables: ["sale_order"],
      queryKey: "home:orders",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 120,
    },
  );

  const { data: taskRows } = useReactiveQuery<TaskRow[]>(
    async () => {
      return (await rdb
        .selectFrom("planning_user_task as t")
        .leftJoin("res_partner as p", "p._ruid", "t.partner_id")
        .select([
          "t._ruid as ruid",
          "t.name as name",
          "t.description as description",
          "p.name as partnerName",
        ])
        .where("t.state", "=", "draft")
        .where("t._delete_date", "is", null)
        .orderBy("t._write_date", "desc")
        .limit(TASK_LIMIT)
        .execute()) as TaskRow[];
    },
    {
      tables: ["planning_user_task", "res_partner"],
      queryKey: "home:tasks",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 120,
    },
  );

  const { data: companyName } = useReactiveQuery<string | null>(
    async () => {
      const company = await rdb
        .selectFrom("res_company")
        .select("name")
        .where("_delete_date", "is", null)
        .limit(1)
        .executeTakeFirst();
      return company?.name ?? null;
    },
    {
      tables: ["res_company"],
      queryKey: "home:company",
      refetchOn: ["insert", "update", "bulk"],
      debounce: 200,
    },
  );

  const stops = computed(() => stopsData.value ?? []);

  const territory = computed(() =>
    companyName.value ? `Presalio SFA · ${companyName.value}` : "Presalio SFA",
  );

  const routeStops = computed<HomeRouteStop[]>(() => {
    const geo = stops.value.filter((s) => s.lat != null && s.lng != null);
    const currentRuid = geo.find((s) => s.status === "upcoming")?.ruid;
    return geo.map((s) => ({
      seq: Number(s.sequence ?? 0),
      name: s.name,
      lat: s.lat as number,
      lng: s.lng as number,
      status: s.ruid === currentRuid ? "current" : s.status,
    }));
  });

  const nextStop = computed<HomeNextStop | null>(() => {
    const upcoming = stops.value.find((s) => s.status === "upcoming");
    if (!upcoming) return null;
    let distanceLabel: string | null = null;
    if (coords.value && upcoming.lat != null && upcoming.lng != null) {
      distanceLabel = formatDistance(
        haversineMeters(coords.value, { lat: upcoming.lat, lng: upcoming.lng }),
      );
    }
    return {
      ruid: upcoming.ruid,
      name: upcoming.name,
      address: composeAddress(upcoming.street, upcoming.street2, upcoming.zip),
      image: partnerImageSrc(upcoming.image),
      distanceLabel,
      visitType: VISIT_TYPE,
    };
  });

  const visitsDone = computed(() => stops.value.filter((s) => s.status === "completed").length);
  const visitsTotal = computed(() => stops.value.length);

  const ordersCount = computed(() => (orderRows.value ?? []).length);
  const revenue = computed(() =>
    (orderRows.value ?? []).reduce((acc, row) => acc + sumOrderLineTotal(row.orderLine), 0),
  );

  const stats = computed<HomeStat[]>(() => [
    { key: "visits", label: "Visits", value: `${visitsDone.value}/${visitsTotal.value}` },
    { key: "orders", label: "Orders", value: String(ordersCount.value) },
    { key: "revenue", label: "Revenue", value: formatDzd(revenue.value) },
  ]);

  const pendingTasks = computed<HomePendingTask[]>(() =>
    (taskRows.value ?? []).map((row) => {
      const { kind, tone } = classifyTask(row.name);
      return {
        ruid: row.ruid,
        kind,
        tone,
        title: row.name,
        partnerName: row.partnerName,
        detail: row.description,
      };
    }),
  );

  const pendingCount = computed(() => pendingTasks.value.length);

  return {
    greeting,
    salespersonName,
    territory,
    routeStops,
    nextStop,
    stats,
    pendingTasks,
    pendingCount,
  };
}
