import { useAuthStore } from "@/shared/stores/auth.store";
import { useServerStore } from "@/shared/stores/server.store";
import { type LoginFormInput, useAuthenticate } from "./useAuthenticate";
import { useMe } from "./useMe";
import { f7 } from "framework7-vue";
import { ref, computed } from "vue";
import { syncOrchestrator } from "@/shared/sync/SyncOrchestrator";

export function useAuth() {
  const authStore = useAuthStore();

  const authQuery = useAuthenticate();
  const meQuery = useMe();

  // Manual loading state to cover the gap between auth and me calls
  const loading = ref(false);
  const syncStatus = ref("");

  // Handle Login Success
  authQuery.onResultSuccess(async (result) => {
    try {
      if (!result) throw new Error("No auth result");

      await authStore.setSession({
        token: result.access_token,
        expires: Date.now() + result.expires_in * 1000,
      });

      // Fetch User Profile
      await meQuery.execute();
    } catch (e: any) {
      loading.value = false;
      syncStatus.value = "";
      f7.dialog.alert(e.message || "Login failed processing", "Error");
    }
  });

  // Handle Me Success
  meQuery.onResultSuccess(async (result) => {
    try {
      if (!result) throw new Error("No user profile result");

      await authStore.setUser({
        ruid: result._ruid,
        name: result.name,
        permissions: result.permissions ?? [],
        remote_partner_id: result.remote_partner_id,
      });

      // Start Initial Sync via Redirect
      // We no longer sync here inline. We let the SyncProcess view handle it.
      f7.views.main.router.navigate("/sync", { reloadCurrent: true });

      // Navigation handled above
    } catch (e: any) {
      loading.value = false; // Stop loading on error that prevents navigation
      f7.dialog.alert("Failed to load user profile: " + e.message, "Error");
    } finally {
      // loading.value = false; // Only stop if we stayed on page, but we navigated.
      // If we navigated, component unmounts. If error caught above, loading false there.
      // If success, we want it explicitly false just in case but after navigation it doesn't matter much.
      if (!loading.value) syncStatus.value = "";
    }
  });

  // Handle Errors
  authQuery.onResultError((error) => {
    loading.value = false;
    f7.dialog.alert(error, "Login Error");
  });

  meQuery.onResultError((error) => {
    loading.value = false;
    f7.dialog.alert("Failed to load user profile: " + error, "Error");
  });

  async function login(form: LoginFormInput) {
    if (loading.value) return;
    loading.value = true;
    syncStatus.value = "";
    await authQuery.execute(form);
  }

  async function logout() {
    await authStore.logout();
    f7.views.main.router.navigate("/login", {
      reloadCurrent: true,
    });
  }

  return {
    login,
    logout,
    loading: computed(() => loading.value),
    syncStatus: computed(() => syncStatus.value),
    isAuthenticated: computed(() => authStore.isAuthenticated),
    user: computed(() => authStore.user),
  };
}
